namespace ghidra.app.plugin.core.data;

using static org.junit.Assert;



using org.junit;

using docking.action;
using docking.widgets;
using ghidra.app.plugin.core.codebrowser;
using ghidra.app.util.datatype;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.test;
using ghidra.util;

public class EditFieldDialogTest : AbstractGhidraHeadedIntegrationTest {
	private TestEnv env;
	private PluginTool tool;
	private Program program;
	private DockingActionIf editFieldAction;
	private EditDataFieldDialog dialog;
	private CodeBrowserPlugin codeBrowser;
	private Structure structure;

	/* @Before */
	public void setUp()
    {
		env = new TestEnv();
		tool = env.getTool();
		tool.addPlugin(typeof(DataPlugin).getName());
		tool.addPlugin(typeof(CodeBrowserPlugin).getName());

		DataPlugin plugin = getPlugin(tool, typeof(DataPlugin));
		codeBrowser = env.getPlugin(typeof(CodeBrowserPlugin));

		program = buildProgram();
		env.open(program);
		env.showTool();
		editFieldAction = getAction(plugin, "Edit Field");
		Data dataAt = program.getListing().getDataAt(addr(0x100));
		structure = (Structure) dataAt.getDataType();
		codeBrowser.toggleOpen(dataAt);
		waitForSwing();
	}

	private Program buildProgram()
    {
		ToyProgramBuilder builder = new ToyProgramBuilder("Test", true);
		builder.createMemory("Test", "0", 1000);
		StructureDataType @struct = new StructureDataType("TestStruct", 4);
		@struct.add(new WordDataType(), "count", "This is the count field");
		@struct.add(new WordDataType(), "color", "This is the color field");
		builder.applyDataType("0x100", @struct);
		return builder.getProgram();

	}

	/* @After */
	public void tearDown()
    {
		env.dispose();
	}

	/* @Test */
	public void testEditDefinedFieldName() {
		goTo(0x104);
		showFieldEditDialog();
		assertEquals("count", structure.getComponent(4).getFieldName());
		assertEquals("count", getNameText());

		setNameText("weight");

		pressOk();
		waitForTasks();
		assertEquals("weight", structure.getComponent(4).getFieldName());
	}

	/* @Test */
	public void testEditDefinedFieldComment() {
		goTo(0x104);
		showFieldEditDialog();
		assertEquals("This is the count field", structure.getComponent(4).getComment());
		assertEquals("This is the count field", getCommentText());

		setCommentText("This is the weight field");

		pressOk();
		waitForTasks();
		assertEquals("This is the weight field", structure.getComponent(4).getComment());
	}

	/* @Test */
	public void testEditDefinedFieldDataType() {
		goTo(0x104);
		showFieldEditDialog();
		assertEquals("word", structure.getComponent(4).getDataType().getDisplayName());
		assertEquals("word", getDataTypeText());

		setDataType(new CharDataType());

		pressOk();

		waitForTasks();
		assertFalse(isDialogVisible());

		assertEquals("char", structure.getComponent(4).getDataType().getDisplayName());
	}

	/* @Test */
	public void testEditDefinedFieldDataTypeAndNameAndComment() {
		goTo(0x104);
		showFieldEditDialog();
		DataTypeComponent dtc = structure.getComponent(4);
		assertEquals("word", dtc.getDataType().getDisplayName());
		assertEquals("word", getDataTypeText());

		setDataType(new CharDataType());
		setNameText("TestName");
		setCommentText("Flux capacitor relay");

		pressOk();

		waitForTasks();
		assertFalse(isDialogVisible());

		dtc = structure.getComponent(4);
		assertEquals("char", dtc.getDataType().getDisplayName());
		assertEquals("TestName", dtc.getFieldName());
		assertEquals("Flux capacitor relay", dtc.getComment());
	}

	/* @Test */
	public void testEditUndefinedFieldName() {
		goTo(0x101);
		showFieldEditDialog();
		assertNull(structure.getComponent(1).getFieldName());
		assertEquals("", getNameText());

		setNameText("abc");

		pressOk();
		waitForTasks();
		assertEquals("abc", structure.getComponent(1).getFieldName());
		assertEquals("undefined1", structure.getComponent(1).getDataType().getDisplayName());
	}

	/* @Test */
	public void testEditUndefinedComment() {
		goTo(0x101);
		showFieldEditDialog();
		assertNull(structure.getComponent(1).getComment());
		assertEquals("", getCommentText());

		setCommentText("comment");

		pressOk();
		waitForTasks();
		assertEquals("comment", structure.getComponent(1).getComment());
		assertEquals("undefined1", structure.getComponent(1).getDataType().getDisplayName());
	}

	/* @Test */
	public void testEditUndefinedDataType() {
		goTo(0x101);
		showFieldEditDialog();
		assertNull(structure.getComponent(1).getComment());
		assertEquals("undefined", getDataTypeText());

		setDataType(new ByteDataType());

		pressOk();
		waitForTasks();
		assertEquals("byte", structure.getComponent(1).getDataType().getDisplayName());
	}

	/* @Test */
	public void testEditUndefinedDataType_ByTypingText() {
		goTo(0x101);
		showFieldEditDialog();
		assertNull(structure.getComponent(1).getComment());
		assertEquals("undefined", getDataTypeText());

		DataTypeSelectionEditor editor = dialog.getDataTypeEditor();
		DropDownSelectionTextField<DataType> textField = editor.getDropDownTextField();
		setText(textField, "byte");

		pressOk();
		waitForTasks();
		assertEquals("byte", structure.getComponent(1).getDataType().getDisplayName());
	}

	/* @Test */
	public void testAddAddressCheckbox() {
		goTo(0x101);
		showFieldEditDialog();
		assertEquals("", getCommentText());
		pressButtonByText(dialog.getComponent(), "Add Current Address");
		assertEquals("00000101", getCommentText());

		pressOk();
		waitForTasks();
		assertEquals("00000101", structure.getComponent(1).getComment());

		showFieldEditDialog();
		assertEquals("00000101", getCommentText());
		pressButtonByText(dialog.getComponent(), "Add Current Address");
		assertEquals("", getCommentText());

		pressOk();
		assertNull(structure.getComponent(1).getComment());
	}

	/* @Test */
	public void testAddDateCheckbox() {
		string today = DateUtils.formatCompactDate(new Date());
		goTo(0x101);
		showFieldEditDialog();
		assertEquals("", getCommentText());
		pressButtonByText(dialog.getComponent(), "Add Today's Date");
		assertEquals(today, getCommentText());

		pressOk();
		waitForTasks();
		assertEquals(today, structure.getComponent(1).getComment());

		showFieldEditDialog();
		assertEquals(today, getCommentText());
		pressButtonByText(dialog.getComponent(), "Add Today's Date");
		assertEquals("", getCommentText());

		pressOk();
		assertNull(structure.getComponent(1).getComment());
	}

	private bool isDialogVisible() {
		return runSwing(() => dialog.isVisible());
	}

	private void showFieldEditDialog() {
		performAction(editFieldAction, false);
		dialog = waitForDialogComponent(typeof(EditDataFieldDialog));
	}

	private void goTo(long addressOffset) {
		Address address = addr(addressOffset);
		codeBrowser.goToField(address, "Address", 0, 0);
		waitForSwing();
	}

	private Address addr(long offset) {
		return program.getAddressFactory().getDefaultAddressSpace().getAddress(offset);
	}

	private void pressOk() {
		pressButtonByText(dialog, "OK");
	}

	private string getNameText() {
		return runSwing(() => dialog.getNameText());
	}

	private void setNameText(string newName) {
		runSwing(() => dialog.setNameText(newName));
	}

	private string getCommentText() {
		return runSwing(() => dialog.getCommentText());
	}

	private void setCommentText(string newComment) {
		runSwing(() => dialog.setCommentText(newComment));
	}

	private string getDataTypeText() {
		return runSwing(() => dialog.getDataTypeText());
	}

	private void setDataType(DataType dataType) {
		runSwing(() => dialog.setDataType(dataType));
	}
}
